import networkx as nx
import random

def get_graph():
    while True:
        G = nx.Graph()
        G.add_nodes_from(range(23))
        edges = []
        for i in range(23):
            for j in range(i+1, 23):
                edges.append((i, j))
        random.shuffle(edges)

        for u, v in edges:
            G.add_edge(u, v)
            # check girth
            try:
                cycles = nx.find_cycle(G, orientation='ignore')
                if len(cycles) < 6:
                    G.remove_edge(u, v)
            except nx.NetworkXNoCycle:
                pass

            if G.number_of_edges() >= 26:
                # check colorability
                d = nx.coloring.greedy_color(G, strategy='largest_first')
                if max(d.values()) < 4:
                    return G

