from z3 import *

V = 23
E = [[Bool(f"e_{i}_{j}") if i < j else False for j in range(V)] for i in range(V)]

s = Solver()

# At least 26 edges
s.add(Sum([If(E[i][j], 1, 0) for i in range(V) for j in range(i+1, V)]) >= 26)

# Colorable with 4 colors
C = [Int(f"c_{i}") for i in range(V)]
for i in range(V):
    s.add(C[i] >= 0, C[i] <= 3)
for i in range(V):
    for j in range(i+1, V):
        s.add(Implies(E[i][j], C[i] != C[j]))

# Girth >= 6 (no cycles of length 3, 4, 5)
# Length 3
for i in range(V):
    for j in range(i+1, V):
        for k in range(j+1, V):
            s.add(Not(And(E[i][j], E[j][k], E[i][k])))

# Length 4
for i in range(V):
    for j in range(i+1, V):
        for k in range(j+1, V):
            for l in range(k+1, V):
                # cycles on i, j, k, l
                # 3 possible 4-cycles
                s.add(Not(And(E[i][j], E[j][k], E[k][l], E[i][l])))
                s.add(Not(And(E[i][j], E[j][l], E[l][k], E[i][k])))
                s.add(Not(And(E[i][k], E[k][j], E[j][l], E[i][l])))

# Length 5
import itertools
for c in itertools.combinations(range(V), 5):
    # 12 possible 5-cycles
    for p in itertools.permutations(c):
        # to avoid duplicates, fix the first element to be the minimum, and the second < last
        if p[0] == min(p) and p[1] < p[4]:
            s.add(Not(And(
                E[min(p[0], p[1])][max(p[0], p[1])],
                E[min(p[1], p[2])][max(p[1], p[2])],
                E[min(p[2], p[3])][max(p[2], p[3])],
                E[min(p[3], p[4])][max(p[3], p[4])],
                E[min(p[4], p[0])][max(p[4], p[0])]
            )))

if s.check() == sat:
    m = s.model()
    edges = []
    for i in range(V):
