def heawood_graph():
    edges = []
    # The Heawood graph can be constructed as the incidence graph of the Fano plane.
    # Or simply as a bipartite graph.
    # Let's use the standard construction:
    # Vertices 0 to 13.
    # Edges: (i, (i+1)%14), (i, (i+5)%14) for even i.
    for i in range(14):
        edges.append((i, (i+1)%14))
    for i in range(0, 14, 2):
        edges.append((i, (i+5)%14))
    return edges

